async function loadFauna(world2) {
  const deer = await new GLTFLoader().loadAsync("./models/deer.glb");
  const prepared2 = prepareDeerAnimations(three_module_exports, deer);
  deer.animations = prepared2.animations;
  deer.motionStats = prepared2.stats;
  boundFaunaTemplate(deer.scene);
  world2.faunaTemplates = { deer };
  for (const e of world2.entities.values()) {
    if (!world2.faunaTemplates[e.type]) continue;
    const old = e.mesh, model = createFauna(e.type, world2.faunaTemplates);
    model.position.copy(old.position);
    model.rotation.copy(old.rotation);
    old.parent.add(model);
    old.parent.remove(old);
    e.mesh = model;
    model.visible = Math.hypot(e.x - world2.playerPos.x, e.z - world2.playerPos.z) < 95;
  }
}
