function createFauna(type, templates) {
  const template3 = templates[type], group = new Group(), model = clone(template3.scene);
  group.add(model);
  model.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = !/^eyes?$/i.test(o.name || "");
      o.receiveShadow = true;
      o.frustumCulled = !o.isSkinnedMesh || !!o.userData.faunaBounds;
    }
  });
  const mixer = new AnimationMixer(model), actions = {};
  for (const clip5 of template3.animations) actions[clip5.name] = mixer.clipAction(clip5);
  actions.Idle?.play();
  const contactShadow = actorContact(type === "deer" ? 2 : 1.5, type === "deer" ? 3 : 2.2, 0.5);
  group.add(contactShadow);
  group.userData = { combatHeight: type === "deer" ? 2 : 1.25, legs: [], type, contactShadow, fauna: { model, mixer, actions, current: "Idle" } };
  return group;
}
function animateFauna(entity, dt, speed = 0) {
  const fauna = entity.mesh.userData.fauna;
  if (!fauna) return;
  if (advanceDeerAnimation(three_module_exports, fauna, entity, dt, speed)) return;
  let next = entity.hp <= 0 ? "Death" : entity.biting > 0 ? "Attack" : speed > 0.05 ? "Run" : entity.type === "deer" && Math.sin(entity.phase * 0.2) > 0.3 ? "Eat" : "Idle";
  if (!fauna.actions[next]) next = "Idle";
  if (next !== fauna.current) {
    const action = fauna.actions[next];
    action.reset().fadeIn(0.22).play();
    if (next === "Death") {
      action.setLoop(LoopOnce, 1);
      action.clampWhenFinished = true;
    }
    fauna.actions[fauna.current]?.fadeOut(0.22);
    fauna.current = next;
  }
  fauna.mixer.update(dt * (next.startsWith("Run") ? Math.max(0.3, speed / 4) : 1));
}
async function loadFerns(world2) {
  const gltf = await new GLTFLoader().loadAsync("./models/fern.glb");
  gltf.scene.updateMatrixWorld(true);
  let source2;
  gltf.scene.traverse((o) => {
    if (o.isMesh && !source2) source2 = o;
  });
  if (!source2) throw new Error("Fern mesh is missing");
  const geometry3 = source2.geometry.clone().applyMatrix4(source2.matrixWorld), material2 = source2.material.clone();
  material2.alphaMap = null;
  for (const map of [material2.map, material2.normalMap, material2.roughnessMap]) if (map) map.anisotropy = 8;
  material2.normalScale.set(0.65, 0.65);
  material2.alphaTest = 0.48;
  material2.side = DoubleSide;
  material2.alphaToCoverage = true;
  material2.roughness = 0.95;
  material2.color.set(14805192);
  material2.emissive.copy(material2.color);
  material2.emissiveMap = material2.map;
  material2.emissiveIntensity = 0.14;
  material2.onBeforeCompile = (s) => {
    s.uniforms.uTime = { value: world2.time };
    s.vertexShader = "uniform float uTime;\n" + s.vertexShader;
    s.vertexShader = s.vertexShader.replace("#include <begin_vertex>", "#include <begin_vertex>\ntransformed.x+=sin(uTime*1.2+instanceMatrix[3].x*.4+instanceMatrix[3].z*.23+position.x*2.)*.15*position.y*position.y;");
    material2.userData.shader = s;
  };
  const oldGeo = world2.fernGeo, oldMat = world2.fernMat;
  world2.fernGeo = geometry3;
  world2.fernMat = material2;
  for (const chunk of world2.chunks.values()) chunk.group.traverse((o) => {
    if (o.name === "forest-fern") {
      o.geometry = geometry3;
      o.material = material2;
      o.computeBoundingSphere();
    }
  });
  refreshEcologyFerns(world2);
  oldGeo.dispose();
  oldMat.dispose();
}
async function loadGuardian(world2) {
  world2.guardianTemplate = await new GLTFLoader().loadAsync("./models/guardian.glb");
  for (const e of world2.entities.values()) if (e.type === "boss" || e.type === "sentinel") {
    const mesh2 = createGuardian(world2, e.type === "boss");
    mesh2.position.copy(e.mesh.position);
    e.mesh.parent.add(mesh2);
    e.mesh.parent.remove(e.mesh);
    e.mesh = mesh2;
  }
}
function createGuardian(world2, boss = false) {
  const gltf = world2.guardianTemplate, group = new Group(), model = clone(gltf.scene);
  model.scale.setScalar(boss ? 1.85 : 0.77);
  group.add(model);
  model.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = o.receiveShadow = true;
      o.frustumCulled = false;
    }
  });
  const mixer = new AnimationMixer(model), actions = {};
  for (const clip5 of gltf.animations) {
    const action = mixer.clipAction(clip5);
    if (/Attack|Death/.test(clip5.name)) {
      action.setLoop(LoopOnce, 1);
      action.clampWhenFinished = true;
    }
    actions[clip5.name] = action;
  }
  actions.Idle.play();
  const contactShadow = actorContact(boss ? 5 : 2.5, boss ? 5 : 2.5, 0.57);
  group.add(contactShadow);
  group.userData = { combatHeight: 3.4 * (boss ? 1.85 : 0.77), arms: [], legs: [], contactShadow, guardian: { mixer, actions, current: "Idle" } };
  group.userData.guardian.contacts = createGuardianContacts(world2, group, model, boss);
  return group;
}
function animateGuardian(e, dt, speed) {
  const g = e.mesh.userData.guardian;
  if (!g) return;
  const attacking = e.windup > 0 && e.windup <= 0.5 || e.strikeTime > 0;
  const next = e.hp <= 0 ? "Death" : attacking ? "Attack" : e.windup > 0.5 ? "Threaten" : speed > 0.1 ? "Walk" : "Idle";
  if (next !== g.current) {
    const action = g.actions[next];
    action.reset().fadeIn(0.1).play();
    g.actions[g.current]?.fadeOut(0.12);
    g.current = next;
  }
  g.actions[next].setEffectiveTimeScale(next === "Walk" ? Math.max(0.5, speed / (e.type === "boss" ? 2.2 : 1.6)) : 1);
  g.mixer.update(dt);
  updateGuardianContacts(g.contacts, e, dt);
}

