        const tt = Math.max(0, v * (tEnd + lip / this.speed) - lip / this.speed);
        const pre = Math.min(0, v * (tEnd + lip / this.speed) - lip / this.speed);
        const c2 = top.clone().addScaledVector(dir, this.speed * (tt + pre)).add(new Vector3(0, -0.5 * G2 * tt * tt, 0));
        const vel = dir.clone().multiplyScalar(this.speed).add(new Vector3(0, -G2 * tt, 0)).normalize();
