        const ig = new InstancedBufferGeometry();
        ig.index = base.index;
        ig.setAttribute("position", base.attributes.position);
        const seeds = new Float32Array(sprayCount * 4);
        for (let i = 0; i < seeds.length; i++) seeds[i] = Math.random();
        ig.setAttribute("seed", new InstancedBufferAttribute(seeds, 4));
        ig.instanceCount = sprayCount;
