function proximity() {
  nearest = null;
  let best = Infinity;
  if (!world.inDungeon) for (const result of world.content?.discoveries(pos) || []) applyContent(result, null);
  const hand = world.firstPerson?.held.state().weapon;
  for (let o of world.objects()) {
    if (o.gone || state.removed.has(o.id) || o.type === "camp" || o.type === "content" && Math.abs(pos.y - o.y) > 2.6) continue;
    if (o.type === "tree" && hand !== "axe" || o.type === "rock" && hand !== "pickaxe") continue;
    if (world.inDungeon && !world.dungeonLayout.segmentClear(pos, o, 0.08)) continue;
    let d = Math.hypot(pos.x - o.x, pos.z - o.z);
    if (d < (o.radius || 3) && d < best) {
      best = d;
      nearest = o;
    }
    if (["cave", "shrine", "boss"].includes(o.type) && d < 18 && !state.discovered.has(o.type)) {
      state.discovered.add(o.type);
      discover(o.name);
      save();
    }
  }
  const near = survival.target(pos.x, pos.z, yaw);
  if (near && (!nearest || near.distance < best + 0.6)) nearest = near;
  if (nearest) {
    if (nearest.survival) {
      $("#interactType").textContent = nearest.verb;
      $("#interaction kbd").textContent = "E";
    } else {
      $("#interactType").textContent = nearest.type === "content" ? { inspect: "調べる", rest: "休息する", loot: "宝箱を開く", "enter-cave": "洞窟に入る" }[nearest.action] || "調べる" : { tree: "斧で幹を叩く", rock: "つるはしで岩を叩く", herb: "採取する", crystal: "採掘する", memory: "石碑に触れる", cave: "洞窟に入る", exit: "地上へ戻る", chest: "宝箱を開く", shrine: "祈る", boss: "調べる" }[nearest.type] || "調べる";
      $("#interaction kbd").textContent = ["tree", "rock"].includes(nearest.type) ? touchDevice ? "振る" : "クリック" : "E";
    }
    $("#interactName").textContent = nearest.name;
    $("#interaction").classList.remove("hidden");
  } else $("#interaction").classList.add("hidden");
  if (!world.inDungeon) {
    let b = biome(pos.x, pos.z);
    if (!state.biomeSeen.has(b.id)) {
      state.biomeSeen.add(b.id);
      discover(b.name);
    }
  }
}
function updateHUD() {
  if (!survival || !hud) return;
  $("#touchInteract").setAttribute("aria-label", nearest ? nearest.name + "：" + (nearest.verb || "調べる") : "拾う・調べる");
  hud.update(survival.view());
  let b = biome(pos.x, pos.z);
  $("#biomeName").textContent = world.inDungeon ? world.currentCave?.name || "洞窟" : b.name;
  $("#regionSub").textContent = world.inDungeon ? "THE HIDDEN DEPTHS" : b.en;
  $("#weather").textContent = world.inDungeon ? "地下" : world.weather?.state.label || b.weather;
  let degrees = (yaw * 180 / Math.PI % 360 + 360) % 360;
  $("#heading").textContent = ["N", "NW", "W", "SW", "S", "SE", "E", "NE"][Math.round(degrees / 45) % 8];
}
var lastDarkVeil = -1;
var lastMindVeil = -1;
function updateVeils() {
  if (!survival) return;
  const dark = state.started && !state.dead ? darknessShade(survival.state.darkness) : 0, mind = state.started && !state.dead ? Math.max(0, Math.min(1, (VITALS.lowSanity - survival.state.vitals.sanity) / VITALS.lowSanity)) : 0;
  if (Math.abs(dark - lastDarkVeil) > 5e-3) {
    lastDarkVeil = dark;
    $("#darkVeil").style.opacity = dark.toFixed(3);
  }
  if (Math.abs(mind - lastMindVeil) > 5e-3) {
    lastMindVeil = mind;
    const veil = $("#mindVeil");
    veil.style.opacity = (mind * 0.85).toFixed(3);
    veil.classList.toggle("active", mind > 0);
  }
}
function updateResolutionReadout() {
  const output = $("#renderResolutionValue");
  if (!output || !world) return;
  const gl = world.renderer.getContext();
  output.textContent = `現在の描画: ${gl.drawingBufferWidth} × ${gl.drawingBufferHeight}（比率 ${world.renderer.getPixelRatio().toFixed(2)}）`;
  world.renderDiagnostics?.refreshSettings($("#panelContent"));
}
